// Basic structure: an array of stage objects
const results = await db.collection('orders').aggregate([
  // Stage 1: Filter (like WHERE in SQL)
  { $match: { status: 'completed' } },

  // Stage 2: Group and compute (like GROUP BY + SUM in SQL)
  {
    $group: {
      _id: '$category',              // group key
      totalRevenue: { $sum: '$amount' },
      orderCount:   { $count: {} },
      avgOrder:     { $avg: '$amount' }
    }
  },

  // Stage 3: Sort results
  { $sort: { totalRevenue: -1 } },

  // Stage 4: Take top 10
  { $limit: 10 },

  // Stage 5: Rename/reshape fields
  {
    $project: {
      _id: 0,
      category: '$_id',
      totalRevenue: { $round: ['$totalRevenue', 2] },
      orderCount: 1,
      avgOrder: { $round: ['$avgOrder', 2] }
    }
  }
]).toArray();

// $group accumulators — the most important ones
await db.collection('sales').aggregate([
  { $match: { year: 2026 } },
  {
    $group: {
      _id: '$region',
      total:    { $sum: '$amount' },        // sum of all amounts
      count:    { $count: {} },              // number of documents
      average:  { $avg: '$amount' },         // average
      max:      { $max: '$amount' },         // highest single sale
      min:      { $min: '$amount' },         // lowest single sale
      products: { $addToSet: '$productId' }, // unique product IDs (array)
      allAmts:  { $push: '$amount' }         // array of ALL amounts
    }
  }
]).toArray();

// Group by multiple fields — use an object as _id
await db.collection('sales').aggregate([
  {
    $group: {
      _id: { year: { $year: '$date' }, region: '$region' },
      total: { $sum: '$amount' }
    }
  },
  { $sort: { '_id.year': -1, total: -1 } }
]).toArray();

await db.collection('users').aggregate([
  {
    $project: {
      // Include fields
      name: 1,
      email: 1,

      // Exclude fields (can mix with inclusions ONLY for _id)
      _id: 0,
      password: 0,

      // Rename a field
      userId: '$_id',

      // Compute a new field
      fullName: { $concat: ['$firstName', ' ', '$lastName'] },

      // Conditional expression
      status: {
        $cond: {
          if: { $gt: ['$age', 18] },
          then: 'adult',
          else: 'minor'
        }
      },

      // Date extraction
      joinYear: { $year: '$createdAt' },

      // String operations
      emailDomain: {
        $arrayElemAt: [{ $split: ['$email', '@'] }, 1]
      }
    }
  }
]).toArray();

// Source document:
// { _id: 1, product: 'A', tags: ['sale', 'new', 'featured'] }

// After $unwind: { tags: '$tags' } — produces 3 documents:
// { _id: 1, product: 'A', tags: 'sale' }
// { _id: 1, product: 'A', tags: 'new' }
// { _id: 1, product: 'A', tags: 'featured' }

// Count products per tag:
await products.aggregate([
  { $unwind: '$tags' },
  {
    $group: {
      _id: '$tags',
      count: { $count: {} }
    }
  },
  { $sort: { count: -1 } }
]).toArray();

// preserveNullAndEmptyArrays — keep docs with no/empty array
await products.aggregate([
  {
    $unwind: {
      path: '$tags',
      preserveNullAndEmptyArrays: true  // keep products with no tags
    }
  }
]).toArray();

// Build a sales report: monthly revenue by category
const report = await db.collection('orders').aggregate([
  // Filter: only completed orders in 2026
  {
    $match: {
      status: 'completed',
      placedAt: {
        $gte: new Date('2026-01-01'),
        $lt: new Date('2027-01-01')
      }
    }
  },

  // Join with products to get category
  {
    $lookup: {
      from: 'products',
      localField: 'productId',
      foreignField: '_id',
      as: 'product'
    }
  },
  { $unwind: '$product' },

  // Group by month + category
  {
    $group: {
      _id: {
        month: { $month: '$placedAt' },
        category: '$product.category'
      },
      revenue:    { $sum: '$amount' },
      orderCount: { $count: {} }
    }
  },

  // Sort chronologically
  { $sort: { '_id.month': 1, revenue: -1 } },

  // Final shape
  {
    $project: {
      _id: 0,
      month: '$_id.month',
      category: '$_id.category',
      revenue: { $round: ['$revenue', 2] },
      orderCount: 1
    }
  }
]).toArray();

console.table(report);
